set-variable.value:
@{
      var session = context.Request.Headers.GetValueOrDefault("X-Lab-Session-Id", "");
      if (!System.Text.RegularExpressions.Regex.IsMatch(session, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\\z")) { return "InvalidSessionId"; }
      var scenario = context.Request.Headers.GetValueOrDefault("X-Lab-Scenario", "");
      if (scenario != "stateful" && scenario != "stateless") { return "InvalidScenario"; }
      if (context.Request.Url.Query.Count != 0) { return "QueryNotSupported"; }
      var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
      if (!string.Equals(contentType, "application/json", StringComparison.OrdinalIgnoreCase)) { return "JsonContentTypeRequired"; }
      if (context.Request.Body == null) { return "InvalidJson"; }
      var rawBody = context.Request.Body.As<string>(preserveContent: true);
      if (string.IsNullOrWhiteSpace(rawBody)) { return "InvalidJson"; }
      var body = JObject.Parse(rawBody);
      if (body["model"] == null || body["model"].Type != JTokenType.String || (string)body["model"] != (string)context.Variables["labModel"]) { return "InvalidModel"; }
      if (body["stream"] == null || body["stream"].Type != JTokenType.Boolean || (bool)body["stream"]) { return "StreamingNotSupported"; }
      if (body["store"] == null || body["store"].Type != JTokenType.Boolean || (bool)body["store"] != (scenario == "stateful")) { return "InvalidStore"; }
      if (body["conversation"] != null || (body["background"] != null && (body["background"].Type != JTokenType.Boolean || (bool)body["background"]))) { return "UnsupportedConversationMode"; }
      var previous = body["previous_response_id"];
      if (previous != null && (previous.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)previous))) { return "InvalidPreviousResponseId"; }
      var cookieCount = 0;
      var hasCookieValue = false;
      string[] cookieHeaders;
      context.Request.Headers.TryGetValue("Cookie", out cookieHeaders);
      foreach (var part in string.Join(";", cookieHeaders ?? new string[0]).Split(';')) {
        var cookie = part.Trim();
        if (cookie.StartsWith("__AFFINITY_COOKIE__=", StringComparison.Ordinal)) {
          cookieCount++;
          hasCookieValue = cookie.Length > "__AFFINITY_COOKIE__=".Length;
        }
      }
      if (cookieCount > 1) { return "DuplicateAffinityCookie"; }
      if (scenario == "stateless" && (previous != null || cookieCount != 0)) { return "StatelessRoutingContextNotAllowed"; }
      if (previous != null && (cookieCount != 1 || !hasCookieValue)) { return "AffinityCookieRequired"; }
      if (previous == null && cookieCount != 0) { return "UnexpectedAffinityCookie"; }
      return "";
    }

@{
      var host = context.Request.Url.Host;
      if (string.Equals(host, (string)context.Variables["labHostA"], StringComparison.OrdinalIgnoreCase)) { return "backend-a"; }
      if (string.Equals(host, (string)context.Variables["labHostB"], StringComparison.OrdinalIgnoreCase)) { return "backend-b"; }
      return "";
    }
